import{_ as t,o as r,c as s,a2 as a}from"./chunks/framework.ChIlRNAd.js";const p=JSON.parse('{"title":"Mails","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/mails.md","filePath":"fr/guide/mails.md"}'),o={name:"fr/guide/mails.md"};function n(l,e,i,c,d,u){return r(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="mails" tabindex="-1">Mails <a class="header-anchor" href="#mails" aria-label="Permalink to &quot;Mails&quot;">​</a></h1><p>La page <strong>Mails</strong> (<code>/mails</code>) liste les mails Gmail du compte actif. On y cherche, on sélectionne et on agit en masse, avec un délai d&#39;annulation pour les actions réversibles.</p><hr><h2 id="en-tete" tabindex="-1">En-tête <a class="header-anchor" href="#en-tete" aria-label="Permalink to &quot;En-tête&quot;">​</a></h2><ul><li>Titre <strong>Mails</strong> et nombre estimé de résultats (« ~N résultats », estimation fournie par Gmail).</li><li><strong>Actualiser</strong> : recharge la liste.</li><li><strong>Tout sauvegarder sur le NAS</strong> : sauvegarde tous les résultats de la recherche courante dans les <a href="./archives.html">Archives</a> (seuls les mails pas encore archivés sont copiés).</li><li><strong>Créer une règle</strong> (si une recherche est saisie) : ouvre le formulaire de <a href="./rules.html#creer-une-regle">règle</a> ; si la recherche est un seul <code>from:adresse</code>, l&#39;expéditeur est pré-rempli.</li></ul><hr><h2 id="compte-un-compte-ou-«-tous-les-comptes-»" tabindex="-1">Compte : un compte ou « Tous les comptes » <a class="header-anchor" href="#compte-un-compte-ou-«-tous-les-comptes-»" aria-label="Permalink to &quot;Compte : un compte ou « Tous les comptes »&quot;">​</a></h2><p>Quand au moins deux comptes Gmail sont connectés, un sélecteur <strong>Compte Gmail</strong> apparaît au-dessus de la liste. Il propose chaque compte et <strong>Tous les comptes</strong> (adresse <code>/mails?account=all</code>, qui remplace l&#39;ancienne boîte unifiée).</p><p>En mode <strong>Tous les comptes</strong> :</p><ul><li>une colonne <strong>Compte</strong> indique à quel compte appartient chaque mail ;</li><li>les actions sur une sélection sont envoyées compte par compte ;</li><li><strong>Créer une règle</strong> n&#39;est proposé que si la sélection vient d&#39;un seul compte ;</li><li><strong>Ajouter un libellé</strong>, <strong>Tout sauvegarder sur le NAS</strong>, la sélection de tous les résultats et le bouton <strong>Afficher plus</strong> ne sont pas disponibles.</li></ul><hr><h2 id="rechercher" tabindex="-1">Rechercher <a class="header-anchor" href="#rechercher" aria-label="Permalink to &quot;Rechercher&quot;">​</a></h2><p>La barre de recherche accepte la syntaxe Gmail : mots-clés et opérateurs (<code>from:</code>, <code>has:attachment</code>, <code>larger:10M</code>, <code>older_than:1y</code>…). À la validation (<code>Entrée</code>), chaque opérateur devient une <strong>étiquette</strong> que l&#39;on retire d&#39;un clic ; le reste reste en texte libre.</p><h3 id="recherches-rapides-et-recherches-enregistrees" tabindex="-1">Recherches rapides et recherches enregistrées <a class="header-anchor" href="#recherches-rapides-et-recherches-enregistrees" aria-label="Permalink to &quot;Recherches rapides et recherches enregistrées&quot;">​</a></h3><p>Au-dessus de la barre, des puces appliquent une recherche en un clic :</p><table tabindex="0"><thead><tr><th>Puce</th><th>Requête Gmail</th></tr></thead><tbody><tr><td>Tous</td><td><em>(vide)</em></td></tr><tr><td>Non lus</td><td><code>is:unread</code></td></tr><tr><td>Avec PJ</td><td><code>has:attachment</code></td></tr><tr><td>Gros mails &gt; 10 Mo</td><td><code>larger:10m</code></td></tr><tr><td>Promotions &gt; 6 mois</td><td><code>category:promotions older_than:6m</code></td></tr><tr><td>Réseaux sociaux</td><td><code>category:social</code></td></tr><tr><td>Plus d&#39;un an</td><td><code>older_than:1y</code></td></tr><tr><td>Spam</td><td><code>in:spam</code></td></tr><tr><td>Corbeille</td><td><code>in:trash</code></td></tr></tbody></table><p>Vos <strong>recherches enregistrées</strong> s&#39;ajoutent à la suite. Pour en créer une, lancez une recherche puis cliquez sur <strong>Enregistrer la recherche</strong> (le bouton apparaît quand la recherche ne correspond à aucune puce) ; la puce prend pour nom le texte de la requête.</p><p>La recherche et le compte sont dans l&#39;adresse de la page (<code>?q=…&amp;account=…</code>) : un marque-page ou le bouton retour les conservent.</p><hr><h2 id="la-liste" tabindex="-1">La liste <a class="header-anchor" href="#la-liste" aria-label="Permalink to &quot;La liste&quot;">​</a></h2><p>Colonnes : <strong>Expéditeur</strong>, <strong>Objet</strong> (avec extrait, trombone si pièce jointe), <strong>Libellés</strong>, <strong>Taille</strong>, <strong>Date</strong>. Le bouton <strong>Colonnes</strong> masque ou affiche des colonnes. Les mails non lus sont en gras.</p><p>La liste se charge par pages : <strong>Afficher plus</strong> charge la suite, jusqu&#39;à « Tous les mails sont chargés ».</p><p>Le menu <code>⋯</code> de chaque ligne propose <strong>Ouvrir</strong>, <strong>Archiver (retirer de la boîte)</strong>, <strong>Sauvegarder sur le NAS</strong> et <strong>Supprimer</strong>.</p><p>Sur mobile, chaque mail est une carte (expéditeur, date, objet) avec une case à cocher.</p><hr><h2 id="selectionner" tabindex="-1">Sélectionner <a class="header-anchor" href="#selectionner" aria-label="Permalink to &quot;Sélectionner&quot;">​</a></h2><ul><li>Cochez des lignes, ou la case d&#39;en-tête pour toute la page chargée.</li><li><strong>Tous les résultats</strong> : si une recherche est saisie et que toutes les lignes chargées sont cochées, un bandeau indique « Les N mails de cette page sont sélectionnés » avec le lien <strong>Sélectionner les ~N résultats de la recherche</strong>. L&#39;action porte alors sur la requête entière côté serveur, même sur les mails non chargés ; le compteur affiche « ~N sélectionnés ».</li><li><strong>Annuler la sélection</strong> (✕) ou <code>Échap</code> vide la sélection. Changer de recherche ou de compte la vide aussi.</li></ul><h3 id="barre-d-actions" tabindex="-1">Barre d&#39;actions <a class="header-anchor" href="#barre-d-actions" aria-label="Permalink to &quot;Barre d&#39;actions&quot;">​</a></h3><p>Dès qu&#39;un mail est sélectionné, la barre d&#39;actions apparaît :</p><table tabindex="0"><thead><tr><th>Action</th><th>Effet</th></tr></thead><tbody><tr><td><strong>Archiver (retirer de la boîte)</strong></td><td>retire les mails de la boîte de réception Gmail</td></tr><tr><td><strong>Sauvegarder sur le NAS</strong></td><td>copie les mails dans les <a href="./archives.html">Archives</a></td></tr><tr><td><strong>Marquer comme lu</strong> / <strong>Marquer comme non lu</strong></td><td>change l&#39;état de lecture</td></tr><tr><td><strong>Supprimer</strong></td><td>envoie les mails dans la corbeille Gmail</td></tr><tr><td><strong>Ajouter un libellé</strong></td><td>applique un libellé Gmail existant (choisi dans une liste)</td></tr><tr><td><strong>Créer une règle</strong></td><td>ouvre le formulaire de règle, pré-rempli si la sélection vient d&#39;un seul expéditeur</td></tr></tbody></table><p>Sur mobile, la barre est en bas de l&#39;écran : quatre actions visibles, les autres sous <strong>Plus</strong>.</p><hr><h2 id="annuler" tabindex="-1">Annuler <a class="header-anchor" href="#annuler" aria-label="Permalink to &quot;Annuler&quot;">​</a></h2><p><strong>Supprimer</strong> et <strong>Archiver (retirer de la boîte)</strong> ne partent pas tout de suite : un toast affiche par exemple « Suppression de 12 mails dans 10 s » (« Vers la corbeille Gmail · suivi dans Activité ») avec le bouton <strong>Annuler</strong>. Les mails disparaissent aussitôt de la liste ; <strong>Annuler</strong> dans les 10 secondes les remet et rien n&#39;est fait. Après le délai, l&#39;action s&#39;exécute (« Trop tard pour annuler : l&#39;action est déjà en cours » si vous cliquez trop tard).</p><p>Pendant ce délai, la tâche apparaît « En attente » dans <a href="./activity.html">Activité</a>, où elle peut aussi être annulée.</p><p>Les autres actions (lecture, libellé, sauvegarde NAS) partent immédiatement ; leur progression s&#39;affiche en haut de la liste.</p><hr><h2 id="lire-un-mail" tabindex="-1">Lire un mail <a class="header-anchor" href="#lire-un-mail" aria-label="Permalink to &quot;Lire un mail&quot;">​</a></h2><p>Cliquez sur un mail (ou <strong>Ouvrir</strong>) : le lecteur s&#39;ouvre en panneau à droite (plein écran sur mobile).</p><ul><li>En-tête : objet, <strong>De</strong>, <strong>À</strong>, date, libellés.</li><li>Corps du mail dans un cadre isolé, sans scripts. Les <strong>images distantes sont bloquées</strong> (« Images distantes bloquées pour protéger votre vie privée. ») ; <strong>Afficher</strong> les charge pour ce mail. Pour les autoriser partout, voir <a href="./settings.html#compte">Paramètres › Compte</a>.</li><li>Pièces jointes téléchargeables, et la <strong>Conversation</strong> (les autres messages du fil).</li><li>Actions : <strong>Archiver (retirer de la boîte)</strong>, <strong>Sauvegarder sur le NAS</strong>, <strong>Supprimer</strong>, <strong>Créer une règle</strong> (pré-remplie avec l&#39;expéditeur).</li></ul><hr><h2 id="raccourcis-clavier" tabindex="-1">Raccourcis clavier <a class="header-anchor" href="#raccourcis-clavier" aria-label="Permalink to &quot;Raccourcis clavier&quot;">​</a></h2><p>Sur ordinateur, sous la liste :</p><table tabindex="0"><thead><tr><th>Touche</th><th>Action</th></tr></thead><tbody><tr><td><code>j</code> / <code>k</code></td><td>mail suivant / précédent</td></tr><tr><td><code>o</code></td><td>ouvrir le mail</td></tr><tr><td><code>e</code></td><td>archiver (retirer de la boîte)</td></tr><tr><td><code>#</code></td><td>supprimer</td></tr><tr><td><code>r</code></td><td>marquer comme lu</td></tr><tr><td><code>u</code></td><td>marquer comme non lu</td></tr><tr><td><code>/</code></td><td>aller à la recherche</td></tr><tr><td><code>Échap</code></td><td>vider la sélection</td></tr></tbody></table><p><code>e</code>, <code>#</code>, <code>r</code> et <code>u</code> agissent sur la sélection, sinon sur le mail qui a le focus. Les raccourcis sont inactifs pendant la saisie et quand le lecteur ou un formulaire est ouvert.</p><p>Ce sont des raccourcis à une touche : le lien <strong>Désactiver</strong> sous la liste (ou l&#39;interrupteur <strong>Raccourcis clavier à une touche</strong> dans <a href="./settings.html#compte">Paramètres › Compte</a>) les coupe, par exemple si vous utilisez une commande vocale. Le choix est mémorisé dans le navigateur.</p>',46)])])}const g=t(o,[["render",n]]);export{p as __pageData,g as default};
